        int stock = sc.nextInt();
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            int req = sc.nextInt();
            try {
                if (req > stock) {
                    throw new InsufficientStockException("Requested " + req + ", but only " + stock + " remaining");
