                System.out.println("Dispensed: " + req + " | Remaining: " + stock);
            } catch (InsufficientStockException e) {
                System.out.println("Error: " + e.getMessage());
            }
        }
        System.out.println("Final Stock: " + stock);
        sc.close();
    }
}

